#!/bin/sh
# Embedded .ko - run: sh ./SCRIPT.sh (no separate .ko file needed)
set -e

# An argument can skip the interactive menu: 1/insmod or 2/ksud.
case "${1:-}" in
    1|insmod)
        LOAD_METHOD=insmod
        ;;
    2|ksud)
        LOAD_METHOD=ksud
        ;;
    "")
        echo 'Select kernel module load method: Telegram channel @PFSR999'
        echo '  1) Normal insmod'
        echo '  2) Jailbreak ksud (KernelSU)'
        printf 'Enter option [1/2]: '
        if ! IFS= read -r CHOICE; then
            echo 'Could not read input. Pass 1 or 2 as a command-line argument instead.' >&2
            exit 2
        fi
        case "$CHOICE" in
            1) LOAD_METHOD=insmod ;;
            2) LOAD_METHOD=ksud ;;
            *) echo 'Invalid option. Enter 1 or 2.' >&2; exit 2 ;;
        esac
        ;;
    *)
        echo 'Invalid argument. Usage: sh SCRIPT.sh [1|2|insmod|ksud]' >&2
        exit 2
        ;;
esac

# Locate ksud only when this method is selected.
if [ "$LOAD_METHOD" = ksud ]; then
    if command -v ksud >/dev/null 2>&1; then
        KSUD_BIN=$(command -v ksud)
    elif [ -x /data/adb/ksud ]; then
        KSUD_BIN=/data/adb/ksud
    elif [ -x /data/adb/ksu/bin/ksud ]; then
        KSUD_BIN=/data/adb/ksu/bin/ksud
    else
        echo 'ksud not found. Make sure KernelSU with insmod support is installed.' >&2
        exit 1
    fi
fi

TMP=$(mktemp)
trap 'rm -f "$TMP"' 0
trap 'exit 130' INT
trap 'exit 143' TERM

base64 -d <<'__EMBEDDED_KO_B64__' > "$TMP"
