__EMBEDDED_KO_B64__

COLOR_GREEN=$(printf '\033[0;32m')
COLOR_RED=$(printf '\033[0;33m')
COLOR_WARN=$(printf '\033[0;33m')
RESET_SEQ=$(printf '\033[0m')

# Figure out the module's real name from its own ELF .modinfo section so a
# stale/previously-loaded copy can be removed before we try to load again.
# "insmod: ... File exists" means the kernel already has a module with this
# name resident — it is NOT a tmp-file collision, so deleting/recreating
# $TMP never helps; the old module has to come out first.
MOD_NAME=""
if command -v modinfo >/dev/null 2>&1; then
    MOD_NAME=$(modinfo "$TMP" 2>/dev/null | awk -F': *' '/^name:/{print $2; exit}')
fi
if [ -z "$MOD_NAME" ]; then
    MOD_NAME=$(strings "$TMP" 2>/dev/null | awk -F= '/^name=/{print $2; exit}')
fi

remove_loaded_module() {
    [ -z "$MOD_NAME" ] && return 1
    lsmod 2>/dev/null | awk '{print $1}' | grep -qx "$MOD_NAME" || return 1
    echo "${COLOR_WARN}Module '$MOD_NAME' is already loaded — removing old copy first${RESET_SEQ}"
    if [ "$LOAD_METHOD" = ksud ]; then
        "$KSUD_BIN" rmmod "$MOD_NAME" >/dev/null 2>&1
    else
        rmmod "$MOD_NAME" >/dev/null 2>&1
    fi
}

load_module() {
    if [ "$LOAD_METHOD" = ksud ]; then
        "$KSUD_BIN" insmod "$TMP" 2>&1
    else
        insmod "$TMP" 2>&1
    fi
}

# Pre-emptively clear out a stale load before the first attempt.
remove_loaded_module || true

set +e
ERROR_MSG=$(load_module)
INSMOD_STATUS=$?

# If it still failed with "File exists", the module was loaded under a
# name/instance we couldn't see via lsmod (or modinfo/strings weren't
# available to find MOD_NAME) — force-remove by name and retry exactly once.
if [ "$INSMOD_STATUS" -ne 0 ] && printf '%s' "$ERROR_MSG" | grep -qi 'File exists'; then
    if [ -n "$MOD_NAME" ]; then
        echo "${COLOR_WARN}Load failed (module already resident) — retrying after removing '$MOD_NAME'${RESET_SEQ}"
        if [ "$LOAD_METHOD" = ksud ]; then
            "$KSUD_BIN" rmmod "$MOD_NAME" >/dev/null 2>&1
        else
            rmmod "$MOD_NAME" >/dev/null 2>&1
        fi
        ERROR_MSG=$(load_module)
        INSMOD_STATUS=$?
    fi
fi
set -e

if [ "$INSMOD_STATUS" -eq 0 ]; then
    echo "${COLOR_GREEN}Kernel module loaded successfully${RESET_SEQ}"
    dmesg | tail -50 | grep -i paradise || true
else
    echo "${COLOR_RED}Driver load failed${RESET_SEQ}"
    echo "$ERROR_MSG"
    if printf '%s' "$ERROR_MSG" | grep -qi 'File exists'; then
        echo "${COLOR_WARN}The module is still resident in the kernel and could not be removed automatically.${RESET_SEQ}"
        echo "${COLOR_WARN}Reboot the device, or run manually: rmmod ${MOD_NAME:-<module_name>}${RESET_SEQ}"
    fi
    dmesg | tail -50 | grep -i paradise || true
    exit 1
fi
